+function convertMarkdownLinks(text: string, options: LinkStyleOptions): string {
+  let result = '';
+  let index = 0;
+  while (index < text.length) {
+    const parsed = parseMarkdownLink(text, index);
+    if (!parsed || (parsed.image ? options.imageStyle : options.linkStyle) !== 'wiki' || parsed.target.includes('://')) {
+      result += text[index++];
+      continue;
+    }
+    const display = unescapeMarkdown(parsed.label);
+    const target = parsed.target;
+    if (parsed.image) {
+      result += `![[${target}${display === '' || display === target ? '' : '|' + display}]]`;
+    } else {
+      result += `[[${target}${display === target || display === defaultDisplay(target) ? '' : '|' + display}]]`;
+    }
+    index = parsed.end;
+  }
+  return result;
+}
+
+function parseMarkdownLink(text: string, start: number): MarkdownLink {
+  const image = text[start] === '!';
+  const labelStart = image ? start + 1 : start;
+  if (text[labelStart] !== '[') return null;
+  const labelEnd = findBalanced(text, labelStart, '[', ']');
+  if (labelEnd === -1 || text[labelEnd + 1] !== '(') return null;
+  const destinationEnd = findBalanced(text, labelEnd + 1, '(', ')');
+  if (destinationEnd === -1) return null;
+  const label = text.slice(labelStart + 1, labelEnd);
+  const rawDestination = text.slice(labelEnd + 2, destinationEnd);
+  if (label.includes('\
') || rawDestination.includes('\
')) return null;
+  const target = parseDestination(rawDestination);
+  if (target === null) return null;
+  return {end: destinationEnd + 1, image, label, target};
+}
+
+function findBalanced(text: string, start: number, open: string, close: string): number {
+  let depth = 0;
+  for (let index = start; index < text.length; index++) {
+    if (text[index] === '\\\') {
+      index++;
+      continue;
+    }
+    if (text[index] === open) depth++;
+    if (text[index] === close && --depth === 0) return index;
+  }
+  return -1;
+}
+
+function parseDestination(rawDestination: string): string | null {
+  const destination = rawDestination.trim();
+  if (destination.startsWith('<')) {
+    const closing = findUnescapedClosingAngle(destination);
+    if (closing !== destination.length - 1) return null;
+    return unescapeMarkdown(destination.slice(1, -1));
+  }
+  if (hasUnescapedWhitespace(destination)) return null;
+  return unescapeMarkdown(destination);
+}
+
+function findUnescapedClosingAngle(text: string): number {
+  for (let index = 1; index < text.length; index++) {
+    if (text[index] === '\\\') {
+      index++;
+    } else if (text[index] === '>') {
+      return index;
+    }
+  }
+  return -1;
+}
+
+function hasUnescapedWhitespace(text: string): boolean {
+  for (let index = 0; index < text.length; index++) {
+    if (text[index] === '\\\') {
+      index++;
+    } else if (/\\s/.test(text[index])) {
+      return true;
+    }
+  }
+  return false;
+}
+
+function unescapeMarkdown(text: string): string {
+  return text.replace(/\\\\(.)/g, '$1');
+}
+
+function defaultDisplay(target: string): string {
+  const heading = target.indexOf('#');
+  if (heading === -1) return target;
+  const page = target.slice(0, heading);
+  const section = target.slice(heading + 1);
+  return page === '' ? section : `${page} > ${section}`;
